@layer moduix.components {
  .root {
    --_badge-height: 1.25rem;
    --_badge-padding-x: var(--moduix-spacing-2-5);
    --_badge-font-size: var(--moduix-text-xs);
    --_badge-line-height: var(--moduix-line-height-text-xs);

    display: inline-flex;
    width: fit-content;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-badge-gap, var(--moduix-spacing-1-5));
    overflow: hidden;
    border: var(--moduix-badge-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-badge-border-color, transparent);
    border-radius: var(--moduix-badge-radius, var(--moduix-radius-full));
    padding-block: var(--moduix-badge-padding-y, 0);
    padding-inline: var(--moduix-badge-padding-x, var(--_badge-padding-x));
    background-color: var(--moduix-badge-bg, var(--moduix-color-primary));
    color: var(--moduix-badge-color, var(--moduix-color-primary-foreground));
    font-size: var(--moduix-badge-font-size, var(--_badge-font-size));
    font-weight: var(--moduix-badge-font-weight, var(--moduix-weight-medium));
    font-variant-numeric: tabular-nums;
    line-height: var(--moduix-badge-line-height, var(--_badge-line-height));
    min-height: var(--moduix-badge-height, var(--_badge-height));
    user-select: none;
    white-space: nowrap;
    text-decoration: none;
    vertical-align: middle;
    transition:
      color var(--moduix-transition-default),
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      opacity var(--moduix-transition-default);

    &:focus-visible {
      outline: var(--moduix-focus-ring-width, var(--moduix-border-width-md)) solid
        var(--moduix-color-ring);
      outline-offset: var(--moduix-focus-ring-offset);
    }

    &:is(a) {
      cursor: pointer;

      @media (hover: hover) {
        &:is(
            [data-variant='default'],
            [data-variant='secondary'],
            [data-variant='destructive']
          ):hover {
          opacity: var(--moduix-opacity-hover);
        }

        &[data-variant='outline']:hover {
          border-color: var(--moduix-badge-border-color, var(--moduix-color-primary));
          color: var(--moduix-badge-color, var(--moduix-color-primary));
        }

        &[data-variant='ghost']:hover {
          color: var(--moduix-badge-color, var(--moduix-color-primary));
        }

        &[data-variant='link']:hover {
          text-decoration-color: currentColor;
        }
      }
    }

    & > svg {
      width: var(--moduix-badge-icon-size, var(--moduix-spacing-3));
      height: var(--moduix-badge-icon-size, var(--moduix-spacing-3));
      flex-shrink: 0;
      pointer-events: none;
    }

    &[data-size='sm'] {
      --_badge-height: 1rem;
      --_badge-padding-x: var(--moduix-spacing-2);
      --_badge-font-size: 0.625rem;
      --_badge-line-height: 0.875rem;
    }

    &[data-size='lg'] {
      --_badge-height: 1.5rem;
      --_badge-padding-x: var(--moduix-spacing-3);
      --_badge-font-size: var(--moduix-text-sm);
      --_badge-line-height: var(--moduix-line-height-text-sm);
    }

    &[data-variant='secondary'] {
      background-color: var(--moduix-badge-bg, var(--moduix-color-secondary));
      color: var(--moduix-badge-color, var(--moduix-color-secondary-foreground));
    }

    &[data-variant='destructive'] {
      background-color: var(--moduix-badge-bg, var(--moduix-color-destructive));
      color: var(--moduix-badge-color, var(--moduix-color-destructive-foreground));
    }

    &[data-variant='outline'] {
      border-color: var(--moduix-badge-border-color, var(--moduix-color-border));
      background-color: var(--moduix-badge-bg, transparent);
      color: var(--moduix-badge-color, var(--moduix-color-foreground));
    }

    &[data-variant='ghost'] {
      background-color: var(--moduix-badge-bg, transparent);
      color: var(--moduix-badge-color, var(--moduix-color-foreground));
    }

    &[data-variant='link'] {
      min-height: auto;
      border-radius: 0;
      padding-block: 0.125em;
      padding-inline: 0;
      background-color: var(--moduix-badge-bg, transparent);
      color: var(--moduix-badge-color, var(--moduix-color-primary));
      text-decoration: underline;
      text-decoration-color: color-mix(in oklab, currentColor 55%, transparent);
      text-underline-offset: 0.15em;
      text-decoration-thickness: from-font;
    }
  }

  .dot {
    width: var(--moduix-badge-dot-size, var(--moduix-spacing-1-5));
    height: var(--moduix-badge-dot-size, var(--moduix-spacing-1-5));
    flex-shrink: 0;
    border-radius: 50%;
    background-color: currentColor;
  }

  .label {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
  }
}

export { default as Badge } from './Badge.vue';
export { default as BadgeDot } from './BadgeDot.vue';
export { default as BadgeLabel } from './BadgeLabel.vue';

export type { Props as BadgeRootProps, BadgeSize, BadgeVariant } from './Badge.vue';
